// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract KawnixStaking is ReentrancyGuard, Pausable, Ownable {
    IERC20 public immutable kawToken;

    // Staking thresholds in USD (1e18 scale)
    uint256 public proUsdRequirement = 2000 * 1e18;
    uint256 public eliteUsdRequirement = 10000 * 1e18;

    struct Stake {
        uint256 amountKAW;
        uint256 usdValueAtStake;
        uint256 startTime;
        uint256 unlockTime;
        uint8 tier; // 0: Standard, 1: PRO, 2: ELITE
        bool active;
    }

    mapping(address => Stake) public stakes;

    event Staked(address indexed user, uint256 amount, uint8 tier, uint256 unlockTime);
    event Unstaked(address indexed user, uint256 amount);
    event EmergencyUnstaked(address indexed user, uint256 amount);

    constructor(address _kawToken, address initialOwner) Ownable(initialOwner) {
        require(_kawToken != address(0), "Invalid token address");
        kawToken = IERC20(_kawToken);
    }

    /**
     * @notice Stakes KAW tokens to gain PRO (1) or ELITE (2) status
     * @param kawAmount Total KAW tokens transferred (in 1e18 units)
     * @param targetTier 1 for PRO, 2 for ELITE
     * @param currentKawUsdPrice Current price of 1 KAW in USD (scaled by 1e18)
     */
    function stake(uint256 kawAmount, uint8 targetTier, uint256 currentKawUsdPrice) 
        external 
        nonReentrant 
        whenNotPaused 
    {
        require(targetTier == 1 || targetTier == 2, "Invalid target tier");
        require(!stakes[msg.sender].active, "Active stake already exists");
        require(currentKawUsdPrice > 0, "Invalid price");

        // Calculate USD equivalent value of tokens provided
        uint256 usdValue = (kawAmount * currentKawUsdPrice) / 1e18;
        uint256 requiredUsd = (targetTier == 1) ? proUsdRequirement : eliteUsdRequirement;
        
        require(usdValue >= requiredUsd, "Insufficient USD value for tier");

        uint256 duration = (targetTier == 1) ? 30 days : 90 days;

        // Pull tokens from user to staking contract
        require(kawToken.transferFrom(msg.sender, address(this), kawAmount), "Token transfer failed");

        stakes[msg.sender] = Stake({
            amountKAW: kawAmount,
            usdValueAtStake: usdValue,
            startTime: block.timestamp,
            unlockTime: block.timestamp + duration,
            tier: targetTier,
            active: true
        });

        emit Staked(msg.sender, kawAmount, targetTier, block.timestamp + duration);
    }

    /**
     * @notice Unstakes KAW tokens after lock duration has passed
     */
    function unstake() external nonReentrant {
        Stake storage userStake = stakes[msg.sender];
        require(userStake.active, "No active stake found");
        require(block.timestamp >= userStake.unlockTime, "Stake duration locked");

        uint256 amountToReturn = userStake.amountKAW;
        
        // Reset stake state before token transfer (Security Best Practice)
        userStake.active = false;
        userStake.tier = 0;

        require(kawToken.transfer(msg.sender, amountToReturn), "Token refund failed");

        emit Unstaked(msg.sender, amountToReturn);
    }

    /**
     * @notice Returns current active tier of user
     */
    function getCurrentTier(address user) external view returns (uint8) {
        Stake memory userStake = stakes[user];
        if (!userStake.active || block.timestamp < userStake.unlockTime) {
            return userStake.active ? userStake.tier : 0;
        }
        // Returns 0 (Standard) if stake lock period has expired
        return 0;
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }
}
